    aseal=json.loads(archived(aprefix+'FINAL_SEAL.json'));need(aseal['members']==addon['members'] and len(addon['members'])==13 and addon['complete_file_count']==14,'Metadata addendum members differ')
    need(addon['directories']==aseal['directories'],'Addendum directory closure differs')
    for r in addon['members']+addon['additional_files']:
     b=archived(aprefix+r['path']);need(sha(b)==r['sha256'] and len(b)==r['bytes'],'Metadata addendum member differs')
    need({p for p in origins if p.startswith(aprefix)}=={aprefix+r['path'] for r in addon['members']+addon['additional_files']},'Complete metadata addendum aliases differ')
    amap=json.loads(archived(aprefix+'METADATA_SCOPE_MAP.json'));need(len(amap['all_imported_role_locations'])==32 and len(amap['three_ambiguous_fields'])==3,'Historical scope map differs')
    for row in amap['all_imported_role_locations']:
     obj=json.loads(source(row['file']))
     for key in row['pointer'].lstrip('/').split('/'):obj=obj[int(key)] if isinstance(obj,list) else obj[key]
     original=json.loads(archived(aprefix+'archive/SOURCE_EXPOSURE.json'))
